type VariantPricingInput = {
  salePrice?: number | null;
  minPrice?: number | null;
};

const MANUAL_ORDER_PRIVATE_RECEIPT_REF_PATTERN =
  /^private:\/\/support-documents\/receipts\/order\/[^\s?#]+$/i;

function normalizeMoney(value?: number | null) {
  return typeof value === 'number' && Number.isFinite(value) ? value : 0;
}

export function getManualOrderUnitPrice(variant: VariantPricingInput) {
  return Math.max(
    normalizeMoney(variant.salePrice),
    normalizeMoney(variant.minPrice),
  );
}

export function getManualOrderContactPhone(
  shippingPhone?: string | null,
  profilePhone?: string | null,
) {
  const normalizedShippingPhone = shippingPhone?.trim();
  if (normalizedShippingPhone) {
    return normalizedShippingPhone;
  }

  return profilePhone?.trim() || '';
}

export function normalizeManualOrderPaymentReceiptRef(
  paymentReceiptRef?: string | null,
) {
  const normalizedPaymentReceiptRef = paymentReceiptRef?.trim();
  return normalizedPaymentReceiptRef || undefined;
}

export function isManualOrderPaymentReceiptRef(
  paymentReceiptRef?: string | null,
) {
  const normalizedPaymentReceiptRef =
    normalizeManualOrderPaymentReceiptRef(paymentReceiptRef);

  return (
    !!normalizedPaymentReceiptRef &&
    MANUAL_ORDER_PRIVATE_RECEIPT_REF_PATTERN.test(
      normalizedPaymentReceiptRef,
    )
  );
}
